//! Offline-only DINOv2 ViT-S/14 similarity prototype.
//!
//! Architecture follows Meta's pinned DINOv2 source at commit
//! `7764ea0f912e53c92e82eb78a2a1631e92725fc8`: 384 channels, 12 blocks, 6 heads,
//! patch size 14, MLP ratio 4, fused QKV, LayerScale initial value 1.0 and
//! LayerNorm epsilon 1e-6. Use [`crate::dinov2_artifact`] for the pinned, immutable
//! size- and SHA-256-verified artifact & [`crate::dinov2_input`] for RGB8 input
//! preparation. The core is not wired into catalog or culling decisions.
//!
//! Modified work (Apache License 2.0, §4(b)): translated to Rust on Candle by
//! Ember contributors (2026), with bounded inputs & explicit validation.
//! Copyright (c) Meta Platforms, Inc. and affiliates. See root NOTICE.
//!
//! References: <https://raw.githubusercontent.com/facebookresearch/dinov2/7764ea0f912e53c92e82eb78a2a1631e92725fc8/dinov2/models/vision_transformer.py>,
//! <https://raw.githubusercontent.com/facebookresearch/dinov2/7764ea0f912e53c92e82eb78a2a1631e92725fc8/dinov2/layers/attention.py>,
//! <https://raw.githubusercontent.com/facebookresearch/dinov2/7764ea0f912e53c92e82eb78a2a1631e92725fc8/dinov2/layers/block.py>.

#![cfg(not(target_arch = "wasm32"))]

use candle_core::{DType, Module, Tensor};
use candle_nn::{Conv2d, Conv2dConfig, LayerNorm, Linear, VarBuilder};

#[cfg(test)]
use candle_core::Device;

use crate::dinov2_positions::position_table;
use crate::nn::{Mlp, ln};
use crate::{Error, Result};

const EMBED: usize = 384;
const DEPTH: usize = 12;
const HEADS: usize = 6;
const HEAD_DIM: usize = EMBED / HEADS;
const PATCH: usize = 14;
const MLP_HIDDEN: usize = EMBED * 4;
const INPUT_224: usize = 224;
const INPUT_518: usize = 518;
const POSITION_TOKENS_518: usize = 1 + (INPUT_518 / PATCH) * (INPUT_518 / PATCH);
const LN_EPS: f64 = 1e-6;

/// Final normalized features returned by DINOv2.
#[derive(Debug)]
pub struct DinoV2Output {
    /// Final LayerNorm CLS token, shape `[1, 384]`.
    pub cls_token: Tensor,
    /// Final LayerNorm patch tokens, shape `[1, N, 384]`.
    pub patch_tokens: Tensor,
}

struct LayerScale {
    gamma: Tensor,
}

impl LayerScale {
    fn new(vb: VarBuilder) -> Result<Self> {
        Ok(Self { gamma: vb.get(EMBED, "gamma")? })
    }

    fn forward(&self, x: &Tensor) -> Result<Tensor> {
        Ok(x.broadcast_mul(&self.gamma)?)
    }
}

struct Attention {
    qkv: Linear,
    proj: Linear,
}

impl Attention {
    fn new(vb: VarBuilder) -> Result<Self> {
        Ok(Self { qkv: candle_nn::linear(EMBED, EMBED * 3, vb.pp("qkv"))?, proj: candle_nn::linear(EMBED, EMBED, vb.pp("proj"))? })
    }

    fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let (batch, tokens, channels) = x.dims3()?;
        if channels != EMBED {
            return Err(Error::Model(format!("DINOv2 attention expected {EMBED} channels, got {channels}")));
        }
        let qkv = self.qkv.forward(x)?.reshape((batch, tokens, 3, HEADS, HEAD_DIM))?.permute((0, 2, 3, 1, 4))?;
        // `permute` leaves strided views; materialize each view before sdpa's matmul.
        let q = qkv.narrow(1, 0, 1)?.squeeze(1)?.contiguous()?;
        let k = qkv.narrow(1, 1, 1)?.squeeze(1)?.contiguous()?;
        let v = qkv.narrow(1, 2, 1)?.squeeze(1)?.contiguous()?;
        let y = crate::nn::sdpa(&q, &k, &v, None, (HEAD_DIM as f64).sqrt().recip())?;
        let y = y.transpose(1, 2)?.reshape((batch, tokens, EMBED))?;
        Ok(self.proj.forward(&y)?)
    }
}

struct Block {
    norm1: LayerNorm,
    attention: Attention,
    ls1: LayerScale,
    norm2: LayerNorm,
    mlp: Mlp,
    ls2: LayerScale,
}

impl Block {
    fn new(index: usize, vb: VarBuilder) -> Result<Self> {
        let vb = vb.pp(format!("blocks.{index}"));
        Ok(Self {
            norm1: ln(EMBED, LN_EPS, vb.pp("norm1"))?,
            attention: Attention::new(vb.pp("attn"))?,
            ls1: LayerScale::new(vb.pp("ls1"))?,
            norm2: ln(EMBED, LN_EPS, vb.pp("norm2"))?,
            mlp: Mlp::new(EMBED, MLP_HIDDEN, true, vb.pp("mlp"))?,
            ls2: LayerScale::new(vb.pp("ls2"))?,
        })
    }

    fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let attention = self.attention.forward(&self.norm1.forward(x)?)?;
        let x = (x + self.ls1.forward(&attention)?)?;
        let mlp = self.mlp.forward(&self.norm2.forward(&x)?)?;
        Ok((&x + self.ls2.forward(&mlp)?)?)
    }
}

/// DINOv2 ViT-S/14 with no preprocessing or checkpoint-path side effects.
pub struct DinoV2 {
    patch_embed: Conv2d,
    cls_token: Tensor,
    /// Kept to force shape validation against official state keys; masks are not exposed here.
    mask_token: Tensor,
    position_224: Tensor,
    position_518: Tensor,
    blocks: Vec<Block>,
    norm: LayerNorm,
}

impl DinoV2 {
    /// Build from a VarBuilder whose caller verified exact artifact size/SHA.
    ///
    /// Candle 0.9.2's path-based `VarBuilder::from_pth` reopens its path for each
    /// tensor, so this constructor has no checkpoint-path input or artifact identity
    /// check. It validates architecture shapes & dtype only. Prefer
    /// [`crate::dinov2_artifact::load_file`] or [`crate::dinov2_artifact::load_verified_bytes`],
    /// which construct tensors from one immutable, verified copy of the pinned `.pth`.
    pub fn from_var_builder(vb: VarBuilder) -> Result<Self> {
        if vb.dtype() != DType::F32 {
            return Err(Error::Model(format!("DINOv2 VarBuilder expects F32 tensors, got {:?}", vb.dtype())));
        }
        let device = vb.device().clone();
        let patch_embed = candle_nn::conv2d(3, EMBED, PATCH, Conv2dConfig { stride: PATCH, ..Default::default() }, vb.pp("patch_embed.proj"))?;
        let cls_token = vb.get((1, 1, EMBED), "cls_token")?;
        let mask_token = vb.get((1, EMBED), "mask_token")?;
        let position = vb.get((1, POSITION_TOKENS_518, EMBED), "pos_embed")?;
        let position_224 = position_table(&position, INPUT_224, &device)?;
        let position_518 = position_table(&position, INPUT_518, &device)?;
        let blocks = (0..DEPTH).map(|i| Block::new(i, vb.clone())).collect::<Result<Vec<_>>>()?;
        let norm = ln(EMBED, LN_EPS, vb.pp("norm"))?;
        Ok(Self { patch_embed, cls_token, mask_token, position_224, position_518, blocks, norm })
    }

    /// Run already normalized F32 pixels with shape `[1, 3, 224, 224]` or `[1, 3, 518, 518]`.
    pub fn forward(&self, pixels: &Tensor) -> Result<DinoV2Output> {
        let height = validate_pixels(pixels)?;
        let patch = self.patch_embed.forward(pixels)?;
        let (_, _, grid_h, grid_w) = patch.dims4()?;
        let tokens = patch.flatten_from(2)?.transpose(1, 2)?;
        let x = Tensor::cat(&[self.cls_token.clone(), tokens], 1)?;
        let position = if height == INPUT_224 { &self.position_224 } else { &self.position_518 };
        let mut x = x.broadcast_add(position)?;
        for block in &self.blocks {
            x = block.forward(&x)?;
        }
        let x = self.norm.forward(&x)?;
        require_finite(&x, "output")?;
        let cls_token = x.narrow(1, 0, 1)?.squeeze(1)?;
        let patch_tokens = x.narrow(1, 1, grid_h * grid_w)?;
        Ok(DinoV2Output { cls_token, patch_tokens })
    }

    /// Cosine similarity for two CLS embeddings; rejects non-finite or zero vectors.
    pub fn cosine(a: &Tensor, b: &Tensor) -> Result<f32> {
        if a.dims() != [1, EMBED] || b.dims() != [1, EMBED] || a.dtype() != DType::F32 || b.dtype() != DType::F32 {
            return Err(Error::Model("DINOv2 cosine expects two F32 [1,384] embeddings".into()));
        }
        let av = a.to_vec2::<f32>()?.into_iter().next().ok_or_else(|| Error::Model("DINOv2 cosine missing first vector".into()))?;
        let bv = b.to_vec2::<f32>()?.into_iter().next().ok_or_else(|| Error::Model("DINOv2 cosine missing second vector".into()))?;
        let (mut dot, mut aa, mut bb) = (0.0f64, 0.0f64, 0.0f64);
        for (&x, &y) in av.iter().zip(&bv) {
            if !x.is_finite() || !y.is_finite() {
                return Err(Error::Model("DINOv2 cosine received non-finite embedding".into()));
            }
            let (x, y) = (x as f64, y as f64);
            dot += x * y;
            aa += x * x;
            bb += y * y;
        }
        if aa <= f64::EPSILON || bb <= f64::EPSILON {
            return Err(Error::Model("DINOv2 cosine received zero embedding".into()));
        }
        Ok((dot / (aa.sqrt() * bb.sqrt())).clamp(-1.0, 1.0) as f32)
    }

    /// Shape-checked mask token retained for future masked-token evaluation.
    pub fn mask_token(&self) -> &Tensor {
        &self.mask_token
    }
}

fn validate_pixels(pixels: &Tensor) -> Result<usize> {
    if pixels.dtype() != DType::F32 {
        return Err(Error::Model(format!("DINOv2 expects F32 pixels, got {:?}", pixels.dtype())));
    }
    let (batch, channels, height, width) = pixels.dims4()?;
    if batch != 1 || channels != 3 || height != width || (height != INPUT_224 && height != INPUT_518) {
        return Err(Error::Model(format!("DINOv2 expects [1,3,224,224] or [1,3,518,518], got {batch:?}x{channels:?}x{height:?}x{width:?}")));
    }
    require_finite(pixels, "input")?;
    Ok(height)
}

/// Check one tensor boundary with one device reduction, avoiding per-layer host readbacks.
fn require_finite(tensor: &Tensor, label: &str) -> Result<()> {
    // `x - x` is zero for every finite x, while NaN and infinities remain NaN;
    // sum propagates that marker without overflow from large finite inputs.
    let finite_marker = tensor.broadcast_sub(tensor)?.sum_all()?.to_scalar::<f32>()?;
    if !finite_marker.is_finite() {
        return Err(Error::Model(format!("DINOv2 {label} contains non-finite values")));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_invalid_pixel_shape() -> Result<()> {
        let pixels = Tensor::zeros((1, 3, 224, 223), DType::F32, &Device::Cpu)?;
        assert!(validate_pixels(&pixels).is_err());
        Ok(())
    }

    #[test]
    fn rejects_nonfinite_pixels() -> Result<()> {
        for bad in [f32::NAN, f32::NEG_INFINITY, f32::INFINITY] {
            let mut values = vec![0.0f32; 3 * INPUT_224 * INPUT_224];
            let last = values.len() - 1;
            values[last] = bad;
            let pixels = Tensor::from_vec(values, (1, 3, INPUT_224, INPUT_224), &Device::Cpu)?;
            assert!(validate_pixels(&pixels).is_err());
        }
        Ok(())
    }

    #[test]
    fn rejects_non_f32_var_builder_before_key_access() {
        let vb = VarBuilder::from_tensors(std::collections::HashMap::new(), DType::F16, &Device::Cpu);
        assert!(DinoV2::from_var_builder(vb).is_err());
    }

    #[test]
    fn attention_materializes_qkv_views_and_matches_reference() -> Result<()> {
        let mut tensors = std::collections::HashMap::new();
        let mut qkv_weight = vec![0.0f32; EMBED * 3 * EMBED];
        for projection in 0..3 {
            let offset = projection * EMBED * EMBED;
            for coordinate in 0..EMBED {
                qkv_weight[offset + coordinate * EMBED + coordinate] = 1.0;
            }
        }
        tensors.insert("qkv.weight".to_string(), Tensor::from_vec(qkv_weight, (EMBED * 3, EMBED), &Device::Cpu)?);
        tensors.insert("qkv.bias".to_string(), Tensor::zeros(EMBED * 3, DType::F32, &Device::Cpu)?);
        let mut projection_weight = vec![0.0f32; EMBED * EMBED];
        for coordinate in 0..EMBED {
            projection_weight[coordinate * EMBED + coordinate] = 1.0;
        }
        tensors.insert("proj.weight".to_string(), Tensor::from_vec(projection_weight, (EMBED, EMBED), &Device::Cpu)?);
        tensors.insert("proj.bias".to_string(), Tensor::zeros(EMBED, DType::F32, &Device::Cpu)?);
        let attention = Attention::new(VarBuilder::from_tensors(tensors, DType::F32, &Device::Cpu))?;

        let mut input = vec![0.0f32; 3 * EMBED];
        input[0] = 1.0;
        input[EMBED] = 0.0;
        input[2 * EMBED] = -1.0;
        let output = attention.forward(&Tensor::from_vec(input, (1, 3, EMBED), &Device::Cpu)?)?.to_vec3::<f32>()?;
        let score = 0.125f32;
        let expected = 2.0 * score.sinh() / (1.0 + 2.0 * score.cosh());
        for (actual, target) in [expected, 0.0, -expected].into_iter().enumerate() {
            assert!((output[0][actual][0] - target).abs() < 1e-5);
            for coordinate in 1..EMBED {
                assert!(output[0][actual][coordinate].abs() < 1e-5);
            }
        }
        Ok(())
    }

    #[test]
    fn rejects_zero_or_nonfinite_cosine_inputs() -> Result<()> {
        let zero = Tensor::zeros((1, EMBED), DType::F32, &Device::Cpu)?;
        assert!(DinoV2::cosine(&zero, &zero).is_err());
        let nan = Tensor::from_vec(vec![f32::NAN; EMBED], (1, EMBED), &Device::Cpu)?;
        assert!(DinoV2::cosine(&nan, &nan).is_err());
        Ok(())
    }
}

//! Bounded RGB8 input preparation for DINOv2.
//!
//! The policy follows the pinned DINOv2 evaluation transform's observable contract:
//! resize the short edge, center-crop, convert RGB8 to tensor, then apply ImageNet
//! normalization. The interpolation kernel is implemented here so image decoding and
//! inference do not acquire a runtime image-processing dependency.
//!
//! Source facts: <https://raw.githubusercontent.com/facebookresearch/dinov2/7764ea0f912e53c92e82eb78a2a1631e92725fc8/dinov2/data/transforms.py>
//! (Apache-2.0, Copyright Meta Platforms, Inc. and affiliates). This implementation
//! independently defines the bounded numerical contract documented in
//! `docs/models/dinov2-input-contract.md`; it does not claim byte-for-byte parity with
//! Pillow or torchvision.

#![cfg(not(target_arch = "wasm32"))]

use candle_core::{Device, Tensor};

#[cfg(test)]
use candle_core::DType;

use crate::{Error, Result};

const MAX_PIXELS: usize = 32_000_000;
const MAX_SIDE: usize = 16_384;
const SMALL_SIDE: usize = 224;
const LARGE_SIDE: usize = 518;
const SMALL_RESIZE_SHORT_EDGE: usize = 256;
const LARGE_RESIZE_SHORT_EDGE: usize = 592;
const IMAGE_MEAN: [f64; 3] = [0.485, 0.456, 0.406];
const IMAGE_STD: [f64; 3] = [0.229, 0.224, 0.225];
const BICUBIC_A: f64 = -0.5;
const MAX_FILTER_TAPS: usize = 4 * (MAX_SIDE / SMALL_RESIZE_SHORT_EDGE) + 1;

/// DINOv2 square input variants supported by Ember.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DinoInputSize {
    /// Official DINOv2 evaluation size: 224 crop after a 256 short-edge resize.
    Small224,
    /// Experimental 518 crop after a 592 short-edge resize.
    Large518,
}

impl DinoInputSize {
    /// Square tensor side in pixels.
    pub const fn side(self) -> usize {
        match self {
            Self::Small224 => SMALL_SIDE,
            Self::Large518 => LARGE_SIDE,
        }
    }

    /// Short edge used before center-cropping.
    pub const fn resize_short_edge(self) -> usize {
        match self {
            Self::Small224 => SMALL_RESIZE_SHORT_EDGE,
            Self::Large518 => LARGE_RESIZE_SHORT_EDGE,
        }
    }
}

/// Prepare row-major, interleaved sRGB RGB8 pixels for DINOv2.
///
/// The result is F32, channel-first, and shaped `[1, 3, side, side]`. Input dimensions
/// are checked before any allocation. Resampling is a separable cubic convolution with
/// `A = -0.5`, half-pixel source coordinates, a widened filter for downsampling,
/// clipped and renormalized edge taps, floor-rounded long-edge dimensions,
/// floor-centered crop offsets, and explicit round-to-nearest/clamp-to-`0..=255` RGB8
/// quantization before normalization. These choices are part of Ember's contract; see
/// the model document for the required numerical reference gate.
pub fn preprocess_rgb8(rgb: &[u8], width: usize, height: usize, size: DinoInputSize, device: &Device) -> Result<Tensor> {
    let pixels = width.checked_mul(height).ok_or_else(|| Error::Model("DINOv2 image dimensions overflow".into()))?;
    if width == 0 || height == 0 || width > MAX_SIDE || height > MAX_SIDE || pixels > MAX_PIXELS {
        return Err(Error::Model("DINOv2 image dimensions exceed bounded RGB8 limits".into()));
    }
    let expected = pixels.checked_mul(3).ok_or_else(|| Error::Model("DINOv2 RGB8 length overflow".into()))?;
    if rgb.len() != expected {
        return Err(Error::Model(format!("DINOv2 RGB8 length {}, expected {expected} for {width} × {height}", rgb.len())));
    }

    let side = size.side();
    let short_edge = size.resize_short_edge();
    let (resized_width, resized_height) = resized_shape(width, height, short_edge)?;
    if resized_width < side || resized_height < side {
        return Err(Error::Model("DINOv2 resize is smaller than its center crop".into()));
    }
    let crop_x = (resized_width - side) / 2;
    let crop_y = (resized_height - side) / 2;
    let x_taps = build_taps(width, resized_width, crop_x, side)?;
    let y_taps = build_taps(height, resized_height, crop_y, side)?;
    let plane = side.checked_mul(side).ok_or_else(|| Error::Model("DINOv2 output plane overflow".into()))?;
    let total = plane.checked_mul(3).ok_or_else(|| Error::Model("DINOv2 output size overflow".into()))?;
    let mut accumulated = vec![[0.0f64; 3]; plane];

    // Build reverse vertical coverage so each required source row is filtered
    // horizontally once, rather than recomputing a 2-D tap product per output pixel.
    // This keeps pixel storage proportional to the fixed output plus one source row;
    // the coverage index itself is bounded by the 16,384-pixel input limit.
    let mut vertical_coverage = vec![Vec::<(usize, f64)>::new(); height];
    for (out_y, y_tap) in y_taps.iter().enumerate() {
        for (&source_y, &weight) in y_tap.indices.iter().zip(y_tap.weights.iter()) {
            vertical_coverage.get_mut(source_y).ok_or_else(|| Error::Model("DINOv2 vertical tap out of range".into()))?.push((out_y, weight));
        }
    }
    let mut horizontal = vec![[0.0f64; 3]; side];
    for source_y in 0..height {
        let coverage = vertical_coverage.get(source_y).ok_or_else(|| Error::Model("DINOv2 vertical coverage out of range".into()))?;
        if coverage.is_empty() {
            continue;
        }
        for (out_x, x_tap) in x_taps.iter().enumerate() {
            let mut channels = [0.0f64; 3];
            for (&source_x, &weight) in x_tap.indices.iter().zip(x_tap.weights.iter()) {
                let pixel = source_y
                    .checked_mul(width)
                    .and_then(|v| v.checked_add(source_x))
                    .and_then(|v| v.checked_mul(3))
                    .ok_or_else(|| Error::Model("DINOv2 RGB8 sample offset overflow".into()))?;
                for (channel, value) in channels.iter_mut().enumerate() {
                    let sample = *rgb
                        .get(pixel.checked_add(channel).ok_or_else(|| Error::Model("DINOv2 RGB8 channel offset overflow".into()))?)
                        .ok_or_else(|| Error::Model("DINOv2 RGB8 sample offset out of range".into()))?;
                    *value += weight * f64::from(sample);
                }
            }
            *horizontal.get_mut(out_x).ok_or_else(|| Error::Model("DINOv2 horizontal output out of range".into()))? = channels;
        }
        for &(out_y, y_weight) in coverage {
            for out_x in 0..side {
                let destination = out_y
                    .checked_mul(side)
                    .and_then(|v| v.checked_add(out_x))
                    .ok_or_else(|| Error::Model("DINOv2 output pixel offset overflow".into()))?;
                let source = *horizontal.get(out_x).ok_or_else(|| Error::Model("DINOv2 horizontal sample out of range".into()))?;
                let target = accumulated.get_mut(destination).ok_or_else(|| Error::Model("DINOv2 output offset out of range".into()))?;
                for channel in 0..3 {
                    target[channel] += y_weight * source[channel];
                }
            }
        }
    }

    let mut output = vec![0.0f32; total];
    for (destination, channels) in accumulated.into_iter().enumerate() {
        for (channel, value) in channels.into_iter().enumerate() {
            let encoded = value.round().clamp(0.0, 255.0);
            let normalized = (encoded / 255.0 - IMAGE_MEAN[channel]) / IMAGE_STD[channel];
            if !normalized.is_finite() {
                return Err(Error::Model("DINOv2 preprocessing produced non-finite data".into()));
            }
            let slot = channel
                .checked_mul(plane)
                .and_then(|v| v.checked_add(destination))
                .ok_or_else(|| Error::Model("DINOv2 output channel offset overflow".into()))?;
            let target = output.get_mut(slot).ok_or_else(|| Error::Model("DINOv2 output offset out of range".into()))?;
            *target = normalized as f32;
        }
    }
    Ok(Tensor::from_vec(output, (1, 3, side, side), device)?)
}

#[derive(Clone, Debug)]
struct Taps {
    indices: Vec<usize>,
    weights: Vec<f64>,
}

fn resized_shape(width: usize, height: usize, short_edge: usize) -> Result<(usize, usize)> {
    if width <= height {
        let long = height.checked_mul(short_edge).ok_or_else(|| Error::Model("DINOv2 resized height overflow".into()))? / width;
        Ok((short_edge, long.max(short_edge)))
    } else {
        let long = width.checked_mul(short_edge).ok_or_else(|| Error::Model("DINOv2 resized width overflow".into()))? / height;
        Ok((long.max(short_edge), short_edge))
    }
}

fn build_taps(source: usize, resized: usize, crop: usize, side: usize) -> Result<Vec<Taps>> {
    (0..side)
        .map(|output| {
            let coordinate = crop.checked_add(output).ok_or_else(|| Error::Model("DINOv2 crop coordinate overflow".into()))?;
            let scale = source as f64 / resized as f64;
            let filterscale = scale.max(1.0);
            let support = 2.0 * filterscale;
            let center = (coordinate as f64 + 0.5) * scale;
            if !center.is_finite() || !support.is_finite() {
                return Err(Error::Model("DINOv2 resize coordinate or support is non-finite".into()));
            }
            let left = (center - support + 0.5).trunc() as isize;
            let right = (center + support + 0.5).trunc() as isize;
            let xmin = left.max(0) as usize;
            let xmax = right.min(source as isize) as usize;
            let tap_count = xmax.checked_sub(xmin).ok_or_else(|| Error::Model("DINOv2 resize tap bounds are invalid".into()))?;
            if tap_count == 0 || tap_count > MAX_FILTER_TAPS {
                return Err(Error::Model("DINOv2 resize tap count is out of bounds".into()));
            }
            let mut indices = Vec::with_capacity(tap_count);
            let mut weights = Vec::with_capacity(tap_count);
            let mut sum = 0.0;
            for index in xmin..xmax {
                let weight = bicubic_filter((index as f64 - center + 0.5) / filterscale);
                if !weight.is_finite() {
                    return Err(Error::Model("DINOv2 resize weight is non-finite".into()));
                }
                indices.push(index);
                weights.push(weight);
                sum += weight;
            }
            if !sum.is_finite() || sum.abs() <= f64::EPSILON {
                return Err(Error::Model("DINOv2 resize weights cannot be normalized".into()));
            }
            for weight in &mut weights {
                *weight /= sum;
            }
            Ok(Taps { indices, weights })
        })
        .collect()
}

fn bicubic_filter(distance: f64) -> f64 {
    let x = distance.abs();
    if x <= 1.0 {
        ((BICUBIC_A + 2.0) * x - (BICUBIC_A + 3.0)) * x * x + 1.0
    } else if x < 2.0 {
        ((BICUBIC_A * x - 5.0 * BICUBIC_A) * x + 8.0 * BICUBIC_A) * x - 4.0 * BICUBIC_A
    } else {
        0.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sizes_expose_official_and_experimental_contracts() {
        assert_eq!(DinoInputSize::Small224.side(), 224);
        assert_eq!(DinoInputSize::Small224.resize_short_edge(), 256);
        assert_eq!(DinoInputSize::Large518.side(), 518);
        assert_eq!(DinoInputSize::Large518.resize_short_edge(), 592);
    }

    #[test]
    fn shape_channels_and_constant_values_are_stable() -> Result<()> {
        let rgb = [0u8, 128, 255];
        let tensor = preprocess_rgb8(&rgb, 1, 1, DinoInputSize::Small224, &Device::Cpu)?;
        assert_eq!(tensor.dtype(), DType::F32);
        assert_eq!(tensor.dims(), [1, 3, 224, 224]);
        let channels = tensor.squeeze(0)?.to_vec3::<f32>()?;
        let expected = [
            (0.0 - IMAGE_MEAN[0] as f32) / IMAGE_STD[0] as f32,
            (128.0 / 255.0 - IMAGE_MEAN[1] as f32) / IMAGE_STD[1] as f32,
            (1.0 - IMAGE_MEAN[2] as f32) / IMAGE_STD[2] as f32,
        ];
        for (channel, expected) in expected.into_iter().enumerate() {
            let value = channels
                .get(channel)
                .and_then(|plane| plane.first())
                .and_then(|row| row.first())
                .copied()
                .ok_or_else(|| Error::Model("test tensor shape".into()))?;
            assert!((value - expected).abs() < 1e-6);
        }
        Ok(())
    }

    #[test]
    fn large518_shape_and_constant_channel_values_are_stable() -> Result<()> {
        let rgb = [255u8, 255, 255];
        let tensor = preprocess_rgb8(&rgb, 1, 1, DinoInputSize::Large518, &Device::Cpu)?;
        assert_eq!(tensor.dtype(), DType::F32);
        assert_eq!(tensor.dims(), [1, 3, 518, 518]);
        let values = tensor.squeeze(0)?.to_vec3::<f32>()?;
        let expected = [
            (1.0 - IMAGE_MEAN[0] as f32) / IMAGE_STD[0] as f32,
            (1.0 - IMAGE_MEAN[1] as f32) / IMAGE_STD[1] as f32,
            (1.0 - IMAGE_MEAN[2] as f32) / IMAGE_STD[2] as f32,
        ];
        for (channel, expected) in expected.into_iter().enumerate() {
            let value = values
                .get(channel)
                .and_then(|plane| plane.first())
                .and_then(|row| row.first())
                .copied()
                .ok_or_else(|| Error::Model("test tensor shape".into()))?;
            assert!((value - expected).abs() < 1e-6);
        }
        Ok(())
    }

    #[test]
    fn malformed_lengths_and_bounds_are_rejected() {
        assert!(preprocess_rgb8(&[0; 2], 1, 1, DinoInputSize::Small224, &Device::Cpu).is_err());
        assert!(preprocess_rgb8(&[], 0, 1, DinoInputSize::Small224, &Device::Cpu).is_err());
        assert!(preprocess_rgb8(&[], usize::MAX, usize::MAX, DinoInputSize::Small224, &Device::Cpu).is_err());
        assert!(preprocess_rgb8(&[], usize::MAX, 1, DinoInputSize::Small224, &Device::Cpu).is_err());
        assert!(preprocess_rgb8(&[], 16_385, 1, DinoInputSize::Small224, &Device::Cpu).is_err());
        assert!(preprocess_rgb8(&[], 8_000, 4_001, DinoInputSize::Small224, &Device::Cpu).is_err());
    }

    #[test]
    fn downsample_widens_bicubic_support_and_normalizes_edges() -> Result<()> {
        let taps = build_taps(1_024, 256, 16, 224)?;
        assert!(taps.iter().any(|tap| tap.indices.len() > 4));
        for tap in taps.iter().take(3).chain(taps.iter().rev().take(3)) {
            let sum: f64 = tap.weights.iter().sum();
            assert!((sum - 1.0).abs() < 1e-12);
            assert!(tap.indices.iter().all(|index| *index < 1_024));
        }
        let maximum = build_taps(16_384, 256, 0, 224)?
            .iter()
            .map(|tap| tap.indices.len())
            .max()
            .ok_or_else(|| Error::Model("missing maximum test tap".into()))?;
        assert_eq!(maximum, 256);
        Ok(())
    }

    #[test]
    fn large518_odd_nonsquare_resize_and_crop_shape_are_stable() -> Result<()> {
        let (resized_width, resized_height) = resized_shape(101, 77, LARGE_RESIZE_SHORT_EDGE)?;
        assert_eq!((resized_width, resized_height), (776, 592));
        assert_eq!((resized_width - LARGE_SIDE) / 2, 129);
        assert_eq!((resized_height - LARGE_SIDE) / 2, 37);
        Ok(())
    }

    #[test]
    fn nonsquare_resize_keeps_center_crop_in_middle() -> Result<()> {
        let (resized_width, resized_height) = resized_shape(8, 4, SMALL_RESIZE_SHORT_EDGE)?;
        assert_eq!((resized_width, resized_height), (512, 256));
        assert_eq!((resized_width - SMALL_SIDE) / 2, 144);
        assert_eq!((resized_height - SMALL_SIDE) / 2, 16);

        let taps = build_taps(8, resized_width, 144, SMALL_SIDE)?;
        let first = taps.first().ok_or_else(|| Error::Model("missing test taps".into()))?;
        let middle = taps.get(SMALL_SIDE / 2).ok_or_else(|| Error::Model("missing test taps".into()))?;
        assert!(first.indices.first().copied().unwrap_or(usize::MAX) < middle.indices.first().copied().unwrap_or(0));

        let mut rgb = vec![0u8; 8 * 4 * 3];
        for y in 0..4 {
            for x in 0..8 {
                let pixel = (y * 8 + x) * 3;
                if let Some(red) = rgb.get_mut(pixel) {
                    *red = (x * 32) as u8;
                }
            }
        }
        let tensor = preprocess_rgb8(&rgb, 8, 4, DinoInputSize::Small224, &Device::Cpu)?;
        let values = tensor.squeeze(0)?.to_vec3::<f32>()?;
        let red = values.first().ok_or_else(|| Error::Model("missing red plane".into()))?;
        let left = red.get(112).and_then(|row| row.first()).copied().ok_or_else(|| Error::Model("missing left crop sample".into()))?;
        let center = red.get(112).and_then(|row| row.get(112)).copied().ok_or_else(|| Error::Model("missing center crop sample".into()))?;
        let right = red.get(112).and_then(|row| row.get(223)).copied().ok_or_else(|| Error::Model("missing right crop sample".into()))?;
        assert!(left < center && center < right);
        Ok(())
    }

    #[test]
    fn downsampled_checkerboard_is_antialiased() -> Result<()> {
        let side = 1_024usize;
        let mut rgb = vec![0u8; side * side * 3];
        for y in 0..side {
            for x in 0..side {
                let value = if (x + y) % 2 == 0 { 0 } else { 255 };
                let pixel = (y * side + x) * 3;
                for channel in 0..3 {
                    if let Some(sample) = rgb.get_mut(pixel + channel) {
                        *sample = value;
                    }
                }
            }
        }
        let tensor = preprocess_rgb8(&rgb, side, side, DinoInputSize::Small224, &Device::Cpu)?;
        let values = tensor.squeeze(0)?.to_vec3::<f32>()?;
        let red = values
            .first()
            .and_then(|plane| plane.get(112))
            .and_then(|row| row.get(112))
            .copied()
            .ok_or_else(|| Error::Model("missing checkerboard sample".into()))?;
        let decoded = (f64::from(red) * IMAGE_STD[0] + IMAGE_MEAN[0]) * 255.0;
        assert!((100.0..=155.0).contains(&decoded));
        Ok(())
    }
}

//! DINOv2's pinned positional-table interpolation.
//!
//! This is the non-register DINOv2 path from
//! <https://github.com/facebookresearch/dinov2/blob/7764ea0f912e53c92e82eb78a2a1631e92725fc8/dinov2/models/vision_transformer.py>.
//! DINOv2 supplies `scale_factor=(w0 + 0.1) / 37`, bicubic interpolation, and
//! `antialias=false`. The bicubic coefficients below follow PyTorch's pinned
//! native `upsample_bicubic2d` implementation at
//! <https://github.com/pytorch/pytorch/blob/v2.4.0/aten/src/ATen/native/cuda/UpSample.cuh>
//! (A = -0.75, align-corners=false, and bounded edge reads), rather than a
//! substitute interpolation kernel.
//!
//! Modified work: translated to Rust on Candle by Ember contributors (2026),
//! restricted to cached 224/518 tables with explicit validation.
//! Copyright (c) Meta Platforms, Inc. and affiliates. DINOv2 uses Apache-2.0.
//! PyTorch: BSD-style terms retained in docs/licenses/pytorch-bicubic-LICENSE.txt.
//! See root NOTICE.

#![cfg(not(target_arch = "wasm32"))]

use candle_core::{DType, Device, Tensor};

const EMBED_DIM: usize = 384;
const PRETRAIN_SIDE: usize = 37;
const PRETRAIN_PATCHES: usize = PRETRAIN_SIDE * PRETRAIN_SIDE;
const PRETRAIN_TOKENS: usize = PRETRAIN_PATCHES + 1;
const TARGET_SIDE: usize = 16;
const TARGET_PATCHES: usize = TARGET_SIDE * TARGET_SIDE;
const TARGET_TOKENS: usize = TARGET_PATCHES + 1;
const PATCH_SIZE: usize = 14;
const INTERPOLATE_OFFSET: f64 = 0.1;
const INTERPOLATION_SCALE: f64 = (TARGET_SIDE as f64 + INTERPOLATE_OFFSET) / PRETRAIN_SIDE as f64;
const BICUBIC_A: f64 = -0.75;
const _: () = assert!(518 / PATCH_SIZE == PRETRAIN_SIDE && 224 / PATCH_SIZE == TARGET_SIDE);

/// Validate `position` then adapt the pinned 518-side table to 224-side input.
///
/// Input table must be `[1, 1370, 384]` F32, matching DINOv2 ViT-S/14. The
/// 518-side path returns its original tensor unchanged. The 224-side path
/// copies only after validation to CPU, interpolates there once, and creates
/// the result directly on `device`; callers can cache that result at model
/// load instead of reading back or resampling per frame.
pub(crate) fn position_table(position: &Tensor, input_side: usize, device: &Device) -> crate::Result<Tensor> {
    if position.dtype() != DType::F32 || position.dims() != [1, PRETRAIN_TOKENS, EMBED_DIM] {
        return Err(crate::Error::Model(format!(
            "DINOv2 positional table must be F32 [1, {PRETRAIN_TOKENS}, {EMBED_DIM}], got {:?} {:?}",
            position.dtype(),
            position.dims()
        )));
    }
    if input_side != 518 && input_side != 224 {
        return Err(crate::Error::Model(format!("DINOv2 positional interpolation supports input sides 518 or 224, got {input_side}")));
    }

    let values = position.to_device(&Device::Cpu)?.flatten_all()?.to_vec1::<f32>()?;
    if values.len() != PRETRAIN_TOKENS * EMBED_DIM || values.iter().any(|value| !value.is_finite()) {
        return Err(crate::Error::Model("DINOv2 positional table contains non-finite or invalid data".into()));
    }

    if input_side == 518 {
        return Ok(position.clone());
    }

    let mut output = Vec::with_capacity(TARGET_TOKENS * EMBED_DIM);
    output.extend_from_slice(&values[..EMBED_DIM]);
    for output_y in 0..TARGET_SIDE {
        let (y_base, y_fraction) = interpolation_coordinate(output_y);
        for output_x in 0..TARGET_SIDE {
            let (x_base, x_fraction) = interpolation_coordinate(output_x);
            for channel in 0..EMBED_DIM {
                let mut horizontal = [0.0_f64; 4];
                for (tap, value) in horizontal.iter_mut().enumerate() {
                    let source_y = clamp_index(y_base + tap as isize - 1, PRETRAIN_SIDE);
                    let mut row = [0.0_f64; 4];
                    for (x_tap, sample) in row.iter_mut().enumerate() {
                        let source_x = clamp_index(x_base + x_tap as isize - 1, PRETRAIN_SIDE);
                        // Flattened table starts with one CLS vector; patch rows follow it.
                        let index = EMBED_DIM + (source_y * PRETRAIN_SIDE + source_x) * EMBED_DIM + channel;
                        *sample = f64::from(values[index]);
                    }
                    *value = cubic_interp(row, x_fraction);
                }
                let interpolated = cubic_interp(horizontal, y_fraction) as f32;
                if !interpolated.is_finite() {
                    return Err(crate::Error::Model("DINOv2 positional interpolation produced non-finite data".into()));
                }
                output.push(interpolated);
            }
        }
    }

    if output.len() != TARGET_TOKENS * EMBED_DIM {
        return Err(crate::Error::Model("DINOv2 positional interpolation produced an invalid table size".into()));
    }
    Ok(Tensor::from_vec(output, (1, TARGET_TOKENS, EMBED_DIM), device)?)
}

/// PyTorch's align-corners=false source coordinate with caller-provided scale.
fn interpolation_coordinate(output_index: usize) -> (isize, f64) {
    let source = (output_index as f64 + 0.5) / INTERPOLATION_SCALE - 0.5;
    let base = source.floor();
    (base as isize, source - base)
}

fn clamp_index(index: isize, side: usize) -> usize {
    if index < 0 {
        0
    } else if index >= side as isize {
        side - 1
    } else {
        index as usize
    }
}

/// PyTorch's native bicubic kernel, with A = -0.75.
fn cubic_interp(samples: [f64; 4], t: f64) -> f64 {
    let c0 = cubic_convolution2(t + 1.0, BICUBIC_A);
    let c1 = cubic_convolution1(t, BICUBIC_A);
    let opposite = 1.0 - t;
    let c2 = cubic_convolution1(opposite, BICUBIC_A);
    let c3 = cubic_convolution2(opposite + 1.0, BICUBIC_A);
    samples[0] * c0 + samples[1] * c1 + samples[2] * c2 + samples[3] * c3
}

fn cubic_convolution1(x: f64, a: f64) -> f64 {
    ((a + 2.0) * x - (a + 3.0)) * x * x + 1.0
}

fn cubic_convolution2(x: f64, a: f64) -> f64 {
    ((a * x - 5.0 * a) * x + 8.0 * a) * x - 4.0 * a
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pinned_table_constants_match_dinov2_nonregister_path() {
        assert_eq!(PRETRAIN_TOKENS, 1 + 37 * 37);
        assert_eq!(TARGET_TOKENS, 1 + 16 * 16);
        assert_eq!(PATCH_SIZE, 14);
        assert_eq!(INTERPOLATE_OFFSET, 0.1);
        assert!((INTERPOLATION_SCALE - 16.1 / 37.0).abs() < f64::EPSILON);
        assert_eq!(BICUBIC_A, -0.75);
    }

    #[test]
    fn first_and_last_reference_coordinates_use_pinned_scale() {
        let first = interpolation_coordinate(0);
        let last = interpolation_coordinate(TARGET_SIDE - 1);
        assert_eq!(first.0, 0);
        assert!((first.1 - 0.6490683229813663).abs() < 1e-12);
        assert_eq!(last.0, 35);
        assert!((last.1 - 0.12111801242235984).abs() < 1e-12);
    }

    #[test]
    fn edge_taps_clamp_without_wrapping() {
        assert_eq!(clamp_index(-1, PRETRAIN_SIDE), 0);
        assert_eq!(clamp_index(0, PRETRAIN_SIDE), 0);
        assert_eq!(clamp_index(PRETRAIN_SIDE as isize, PRETRAIN_SIDE), PRETRAIN_SIDE - 1);
        assert_eq!(clamp_index(PRETRAIN_SIDE as isize + 1, PRETRAIN_SIDE), PRETRAIN_SIDE - 1);
    }

    #[test]
    fn bicubic_integer_edges_select_center_taps() {
        let samples = [3.0, 7.0, 11.0, 13.0];
        assert!((cubic_interp(samples, 0.0) - samples[1]).abs() < 1e-12);
        assert!((cubic_interp(samples, 1.0) - samples[2]).abs() < 1e-12);
    }

    fn constant_position(cls: f32, patch: f32) -> crate::Result<Tensor> {
        let mut values = vec![patch; PRETRAIN_TOKENS * EMBED_DIM];
        for value in values.iter_mut().take(EMBED_DIM) {
            *value = cls;
        }
        Ok(Tensor::from_vec(values, (1, PRETRAIN_TOKENS, EMBED_DIM), &Device::Cpu)?)
    }

    #[test]
    fn interpolation_excludes_cls_from_patch_table() -> crate::Result<()> {
        let position = constant_position(-1234.0, 7.0)?;
        let output = position_table(&position, 224, &Device::Cpu)?;
        let values = output.flatten_all()?.to_vec1::<f32>()?;
        assert_eq!(values.len(), TARGET_TOKENS * EMBED_DIM);
        assert_eq!(values.first().copied(), Some(-1234.0));
        assert_eq!(values.get(EMBED_DIM).copied(), Some(7.0));
        assert!(values.iter().skip(EMBED_DIM).all(|value| *value == 7.0));
        Ok(())
    }

    #[test]
    fn invalid_and_nonfinite_tables_are_rejected() -> crate::Result<()> {
        let invalid = Tensor::from_vec(vec![0.0_f32; EMBED_DIM], (1, 1, EMBED_DIM), &Device::Cpu)?;
        assert!(position_table(&invalid, 224, &Device::Cpu).is_err());

        let mut nonfinite_values = vec![0.0_f32; PRETRAIN_TOKENS * EMBED_DIM];
        if let Some(value) = nonfinite_values.get_mut(EMBED_DIM) {
            *value = f32::NAN;
        }
        let nonfinite = Tensor::from_vec(nonfinite_values, (1, PRETRAIN_TOKENS, EMBED_DIM), &Device::Cpu)?;
        assert!(position_table(&nonfinite, 224, &Device::Cpu).is_err());
        Ok(())
    }
}

//! Downloading the SAM 3 model, only when the user asked for it. The downloader itself (mirrors,
//! resuming, checks, the pure-Rust HTTPS client) is the `lightcraft-fetch` crate; this module
//! says what SAM 3 needs and where it may come from.
//!
//! The weights are never part of Ember (SAM License, see docs/ai-masks.md); where they are
//! downloaded from is configured by [`DEFAULT_MIRRORS`] and the user's own list.

pub use lightcraft_fetch::*;

use std::path::Path;

/// The `facebook/sam3` checkpoint files [`crate::Sam3::load`] needs.
///
/// `model.safetensors` is pinned to the official checkpoint (Hugging Face LFS SHA-256). The two
/// tokenizer files are small text files without a pinned hash yet: they are only parsed by the
/// tokenizer (never executed) and capped in size.
// TODO(maintainer): pin `vocab.json` and `merges.txt` (size + SHA-256) when the files are
// uploaded to Ember's CDN.
pub const SAM3_FILES: &[FileSpec] = &[
    FileSpec { name: "vocab.json", size: None, sha256: None, max: 16 << 20 },
    FileSpec { name: "merges.txt", size: None, sha256: None, max: 16 << 20 },
    FileSpec {
        name: crate::WEIGHTS_FILE,
        size: Some(SAM3_WEIGHTS_SIZE),
        sha256: Some("6d06f0a5f84e435071fe6603e61d0b4cc7b40e0d39d487cfd4d67d8cc11cc14a"),
        max: SAM3_WEIGHTS_SIZE,
    },
];

/// Size of the official `model.safetensors` (3.44 GB).
pub const SAM3_WEIGHTS_SIZE: u64 = 3_439_938_512;

/// Where Ember downloads the model from, in order: each is a base URL, and file `f` is at
/// `<base>/<f>`. **Empty for now**: Ember has no download location of its own yet, so the
/// in-app download needs the user's list (`LIGHTCRAFT_SAM3_MIRRORS` or the mirrors file, see
/// [`mirrors`] and docs/ai-masks.md) until this is filled in.
///
/// Hugging Face's `facebook/sam3` can't be a default: it is gated (each user must accept the
/// SAM License there and download with their own token).
// TODO(maintainer): add Ember's CDN locations (https, primary first), e.g.
// "https://<cdn-host>/models/sam3/<revision>" — the files there must match `SAM3_FILES`.
pub const DEFAULT_MIRRORS: &[&str] = &[];

/// Environment variable with extra mirrors (base URLs separated by commas, spaces or newlines),
/// tried before the defaults.
pub const MIRRORS_ENV: &str = "LIGHTCRAFT_SAM3_MIRRORS";

/// The mirrors to try for SAM 3, in order: the environment variable's, then the mirrors file's
/// (one base URL per line, `#` comments), then [`DEFAULT_MIRRORS`].
pub fn mirrors(env: Option<&str>, file: Option<&Path>) -> Vec<String> {
    lightcraft_fetch::mirrors(env, file, DEFAULT_MIRRORS)
}

/// Download settings for SAM 3: the defaults, plus [`TOKEN_ENV`] for a gated mirror.
pub fn options() -> Options {
    Options { token_env: Some(TOKEN_ENV), ..Options::default() }
}

/// Environment variable with a bearer token for the SAM 3 mirror's own host (a gated Hugging Face repository).
pub const TOKEN_ENV: &str =[REDACTED]

/// What to tell the user when there is no mirror for the SAM 3 model.
pub fn no_mirrors_message() -> String {
    format!(
        "no download location is configured for the SAM 3 model in this build (set {MIRRORS_ENV}, or put the files in the model folder yourself; see docs/ai-masks.md)"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sam3_mirrors_come_from_the_environment_the_file_and_the_defaults() {
        let m = mirrors(Some("https://a.example/x/"), Some(Path::new("/nonexistent/mirrors.txt")));
        assert_eq!(m.len(), 1 + DEFAULT_MIRRORS.len());
        assert!(no_mirrors_message().contains(MIRRORS_ENV));
    }
}

//! Maker-note IFD helpers.
//!
//! Most vendors store their maker note (Exif tag 37500) as a TIFF IFD, but each uses its own header,
//! byte order and *offset base* (what stored value offsets are relative to). The header layouts here
//! follow the public descriptions in the ExifTool tag documentation (`MakerNotes` table) and the
//! vendors' own published notes; no third-party code was consulted.

use crate::{ByteOrder, Ifd, ParseOptions, parse_ifd_at};
use serde::{Deserialize, Serialize};

/// Maker-note dialects we know how to locate.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum MakerNoteKind {
    /// Plain IFD at the start of the note, offsets relative to the enclosing TIFF header (Canon, many others).
    Plain,
    /// `Nikon\0` + version + embedded TIFF header at +10; offsets relative to that header.
    NikonV3,
    /// `Nikon\0\x01\0`: IFD at +8, offsets relative to the enclosing TIFF header.
    NikonV1,
    /// `SONY DSC `/`SONY CAM `/`SONY MOBILE` etc.: 12-byte header, offsets relative to the TIFF header.
    Sony,
    /// `FUJIFILM` + LE u32 IFD offset; little-endian, offsets relative to the note start.
    Fujifilm,
    /// `OLYMPUS\0` + byte order + version: IFD at +12, offsets relative to the note start.
    OlympusNew,
    /// `OLYMP\0` / `EPSON\0` etc.: IFD at +8, offsets relative to the TIFF header.
    OlympusOld,
    /// `Panasonic\0\0\0`: IFD at +12, offsets relative to the TIFF header.
    Panasonic,
    /// `AOC\0` + byte order: IFD at +6, offsets relative to the TIFF header.
    PentaxAoc,
    /// `PENTAX \0` + byte order: IFD at +10, offsets relative to the note start.
    Pentax,
}

/// A parsed maker-note IFD.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct MakerNote {
    pub kind: MakerNoteKind,
    pub order: ByteOrder,
    /// Absolute offset that stored value offsets are relative to.
    pub base: u64,
    pub ifd: Ifd,
}

/// Locate and parse the maker note stored at absolute `offset` (length `len`) inside `data`, the buffer whose
/// start is the enclosing TIFF header. `order` is the enclosing stream's byte order. `make` (the Exif Make) is
/// used only as a hint for header-less notes. Returns `None` for unknown or unparsable notes.
pub fn parse_makernote(data: &[u8], offset: u64, len: u64, order: ByteOrder, make: &str) -> Option<MakerNote> {
    let start = usize::try_from(offset).ok()?;
    let end = start.checked_add(usize::try_from(len).ok()?)?.min(data.len());
    let note = data.get(start..end)?;
    let order_at = |i: usize| match note.get(i..i + 2) {
        Some(b"II") => Some(ByteOrder::Little),
        Some(b"MM") => Some(ByteOrder::Big),
        _ => None,
    };
    let opts = ParseOptions { max_ifds: 64, max_depth: 3, ..Default::default() };
    let try_parse = |kind: MakerNoteKind, ifd_at: u64, base: u64, ord: ByteOrder| -> Option<MakerNote> {
        let (ifd, _) = parse_ifd_at(data, ifd_at, ord, base, false, &opts).ok()?;
        (!ifd.entries.is_empty()).then_some(MakerNote { kind, order: ord, base, ifd })
    };
    if note.starts_with(b"Nikon\0") {
        if note.get(6) == Some(&1) {
            return try_parse(MakerNoteKind::NikonV1, offset + 8, 0, order);
        }
        let ord = order_at(10)?;
        let ifd_rel = ord.read_u32(note, 14)? as u64;
        let base = offset + 10;
        return try_parse(MakerNoteKind::NikonV3, base + ifd_rel, base, ord);
    }
    if note.starts_with(b"FUJIFILM") || note.starts_with(b"GENERALE") {
        let rel = ByteOrder::Little.read_u32(note, 8)? as u64;
        return try_parse(MakerNoteKind::Fujifilm, offset + rel, offset, ByteOrder::Little);
    }
    if note.starts_with(b"OLYMPUS\0") || note.starts_with(b"OM SYSTEM\0") {
        let (ord_at, ifd_at) = if note.starts_with(b"OM SYSTEM\0") { (12, 16) } else { (8, 12) };
        let ord = order_at(ord_at).unwrap_or(order);
        return try_parse(MakerNoteKind::OlympusNew, offset + ifd_at, offset, ord);
    }
    for p in [b"OLYMP\0", b"EPSON\0", b"MINOL\0", b"CAMER\0", b"SANYO\0"] {
        if note.starts_with(p) {
            return try_parse(MakerNoteKind::OlympusOld, offset + 8, 0, order);
        }
    }
    if note.starts_with(b"Panasonic\0") {
        return try_parse(MakerNoteKind::Panasonic, offset + 12, 0, order);
    }
    if note.starts_with(b"AOC\0") {
        let ord = order_at(4).unwrap_or(order);
        return try_parse(MakerNoteKind::PentaxAoc, offset + 6, 0, ord);
    }
    if note.starts_with(b"PENTAX \0") {
        let ord = order_at(8).unwrap_or(order);
        return try_parse(MakerNoteKind::Pentax, offset + 10, offset, ord);
    }
    if (note.starts_with(b"SONY") || note.starts_with(b"VHAB     \0"))
        && let Some(m) = try_parse(MakerNoteKind::Sony, offset + 12, 0, order)
    {
        return Some(m);
    }
    let _ = make;
    try_parse(MakerNoteKind::Plain, offset, 0, order)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{IfdBuilder, TiffWriter, Value, tags};

    /// Build a TIFF whose Exif IFD carries `note` as the maker note, return (bytes, note offset, len).
    fn with_note(order: ByteOrder, note: Vec<u8>) -> (Vec<u8>, u64, u64) {
        let mut exif = IfdBuilder::new();
        exif.set(tags::MAKER_NOTE, Value::Undefined(note));
        let mut ifd0 = IfdBuilder::new();
        ifd0.set(tags::MAKE, Value::Ascii("Test".into()));
        ifd0.set_child(tags::EXIF_IFD, exif);
        let bytes = TiffWriter { order, bigtiff: false }.write(&[ifd0]).unwrap();
        let t = crate::Tiff::parse(&bytes).unwrap();
        let e = t.exif().unwrap().get(tags::MAKER_NOTE).unwrap();
        let (off, len) = (e.offset, e.count() as u64);
        (bytes, off, len)
    }

    /// An IFD with one SHORT entry (tag 1, value 7) and one out-of-line LONG[2] entry at `rel` (relative to base).
    fn tiny_ifd(order: ByteOrder, rel_values: u32) -> Vec<u8> {
        let mut v = Vec::new();
        order.put_u16(&mut v, 2);
        order.put_u16(&mut v, 1);
        order.put_u16(&mut v, 3);
        order.put_u32(&mut v, 1);
        order.put_u16(&mut v, 7);
        order.put_u16(&mut v, 0);
        order.put_u16(&mut v, 2);
        order.put_u16(&mut v, 4);
        order.put_u32(&mut v, 2);
        order.put_u32(&mut v, rel_values);
        order.put_u32(&mut v, 0);
        v
    }

    #[test]
    fn nikon_v3_uses_embedded_header_base() {
        for order in [ByteOrder::Little, ByteOrder::Big] {
            let mut note = b"Nikon\0\x02\x10\0\0".to_vec();
            let hdr_at = note.len();
            note.extend_from_slice(if order == ByteOrder::Little { b"II" } else { b"MM" });
            order.put_u16(&mut note, 42);
            order.put_u32(&mut note, 8);
            // IFD at +8 (relative to embedded header), values after IFD: 8 + 2 + 24 + 4 = 38
            note.extend(tiny_ifd(order, 38));
            order.put_u32(&mut note, 111);
            order.put_u32(&mut note, 222);
            let (bytes, off, len) = with_note(order, note);
            let m = parse_makernote(&bytes, off, len, order, "NIKON CORPORATION").unwrap();
            assert_eq!(m.kind, MakerNoteKind::NikonV3);
            assert_eq!(m.base, off + hdr_at as u64);
            assert_eq!(m.ifd.u32(1), Some(7));
            assert_eq!(m.ifd.u64s(2).unwrap(), vec![111, 222]);
        }
    }

    #[test]
    fn fujifilm_offsets_relative_to_note() {
        let mut note = b"FUJIFILM".to_vec();
        ByteOrder::Little.put_u32(&mut note, 12);
        // IFD at 12 (relative to note), values at 12 + 30 = 42
        note.extend(tiny_ifd(ByteOrder::Little, 42));
        ByteOrder::Little.put_u32(&mut note, 5);
        ByteOrder::Little.put_u32(&mut note, 6);
        // enclosing file is big-endian: Fuji notes are always little-endian
        let (bytes, off, len) = with_note(ByteOrder::Big, note);
        let m = parse_makernote(&bytes, off, len, ByteOrder::Big, "FUJIFILM").unwrap();
        assert_eq!(m.kind, MakerNoteKind::Fujifilm);
        assert_eq!(m.order, ByteOrder::Little);
        assert_eq!(m.ifd.u64s(2).unwrap(), vec![5, 6]);
    }

    #[test]
    fn plain_canon_style_note() {
        // Plain IFD whose out-of-line offset is relative to the TIFF header: we need the absolute
        // position, which we only know after writing. Write once to learn the offset, then patch.
        let order = ByteOrder::Little;
        let mut note = tiny_ifd(order, 0);
        note.extend_from_slice(&[0; 8]);
        let (mut bytes, off, len) = with_note(order, note);
        let values_abs = off as u32 + 30;
        bytes[off as usize + 22..off as usize + 26].copy_from_slice(&values_abs.to_le_bytes());
        bytes[off as usize + 30..off as usize + 34].copy_from_slice(&9u32.to_le_bytes());
        let m = parse_makernote(&bytes, off, len, order, "Canon").unwrap();
        assert_eq!(m.kind, MakerNoteKind::Plain);
        assert_eq!(m.ifd.u64s(2).unwrap(), vec![9, 0]);
    }

    #[test]
    fn garbage_note_is_none() {
        let (bytes, off, len) = with_note(ByteOrder::Little, vec![0xff; 40]);
        assert!(parse_makernote(&bytes, off, len, ByteOrder::Little, "X").is_none());
        assert!(parse_makernote(&bytes, 1 << 40, 10, ByteOrder::Little, "X").is_none());
        assert!(parse_makernote(&bytes, off, u64::MAX, ByteOrder::Little, "X").is_none());
    }
}

//! The About window's credits: every contributor (GitHub login always; display and real names only
//! with recorded consent) and the AI models that helped. The tables are baked into the binary by
//! build.rs from contributors/contributors.json (craftrules standards/contributors.md); nothing is
//! read at run time.

use std::cmp::Ordering;

use egui::RichText;

use crate::{LightcraftApp, theme::Tokens};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Contributor {
    pub login: &'static str,
    pub display_name: Option<&'static str>,
    pub real_name: Option<&'static str>,
    pub prs: u64,
    pub commits: u64,
    pub lines_added: u64,
    pub lines_deleted: u64,
    pub binary_added: u64,
    pub binary_deleted: u64,
    /// ISO 8601 UTC; empty for someone credited only through a merged PR.
    pub first_commit: &'static str,
    pub last_commit: &'static str,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Model {
    pub company: &'static str,
    pub model: &'static str,
    pub version: &'static str,
    pub commits: u64,
    pub lines_added: u64,
    pub lines_deleted: u64,
}

include!(concat!(env!("OUT_DIR"), "/credits.rs"));

/// Which name to show. Display and real names fall back to the `@username` when not given.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum NameMode {
    #[default]
    Username,
    DisplayName,
    RealName,
}

impl NameMode {
    pub const ALL: [NameMode; 3] = [NameMode::Username, NameMode::DisplayName, NameMode::RealName];

    pub fn label(self) -> &'static str {
        match self {
            NameMode::Username => "Username",
            NameMode::DisplayName => "Display name",
            NameMode::RealName => "Real name",
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum SortKey {
    Name,
    Prs,
    Commits,
    LinesAdded,
    LinesDeleted,
    LinesDelta,
    BinaryAdded,
    BinaryDeleted,
    #[default]
    FirstCommit,
    LastCommit,
}

impl SortKey {
    pub const ALL: [SortKey; 10] = [
        SortKey::Name,
        SortKey::Prs,
        SortKey::Commits,
        SortKey::LinesAdded,
        SortKey::LinesDeleted,
        SortKey::LinesDelta,
        SortKey::BinaryAdded,
        SortKey::BinaryDeleted,
        SortKey::FirstCommit,
        SortKey::LastCommit,
    ];

    /// Menu label and table header.
    pub fn label(self) -> (&'static str, &'static str) {
        match self {
            SortKey::Name => ("Name (A–Z)", "Name"),
            SortKey::Prs => ("Merged PRs", "PRs"),
            SortKey::Commits => ("Commits", "Commits"),
            SortKey::LinesAdded => ("Lines added", "+LOC"),
            SortKey::LinesDeleted => ("Lines deleted", "−LOC"),
            SortKey::LinesDelta => ("Line delta", "ΔLOC"),
            SortKey::BinaryAdded => ("Binary assets added", "+Bin"),
            SortKey::BinaryDeleted => ("Binary assets removed", "−Bin"),
            SortKey::FirstCommit => ("First commit", "First"),
            SortKey::LastCommit => ("Last commit", "Last"),
        }
    }

    /// Names and dates read naturally oldest/A first; counts read biggest first.
    pub fn default_ascending(self) -> bool {
        matches!(self, SortKey::Name | SortKey::FirstCommit | SortKey::LastCommit)
    }
}

impl Contributor {
    pub fn name(&self, mode: NameMode) -> String {
        let chosen = match mode {
            NameMode::Username => None,
            NameMode::DisplayName => self.display_name,
            NameMode::RealName => self.real_name,
        };
        chosen.map_or_else(|| format!("@{}", self.login), str::to_string)
    }

    pub fn lines_delta(&self) -> i128 {
        i128::from(self.lines_added) - i128::from(self.lines_deleted)
    }

    /// One line with everything we know, for tooltips.
    pub fn summary(&self) -> String {
        crate::i18n::tr_format!(
            "@{}: {} PRs, {} commits, +{} / −{} lines (Δ {}), +{} / −{} binary assets, {} – {}",
            self.login,
            self.prs,
            self.commits,
            group(self.lines_added),
            group(self.lines_deleted),
            signed(self.lines_delta()),
            self.binary_added,
            self.binary_deleted,
            day(self.first_commit),
            day(self.last_commit)
        )
    }
}

/// Alphabetical key: case-insensitive, ignoring the `@` of usernames.
fn name_key(name: &str) -> String {
    name.trim_start_matches('@').to_lowercase()
}

fn compare(a: &Contributor, b: &Contributor, mode: NameMode, key: SortKey) -> Ordering {
    match key {
        SortKey::Name => name_key(&a.name(mode)).cmp(&name_key(&b.name(mode))),
        SortKey::Prs => a.prs.cmp(&b.prs),
        SortKey::Commits => a.commits.cmp(&b.commits),
        SortKey::LinesAdded => a.lines_added.cmp(&b.lines_added),
        SortKey::LinesDeleted => a.lines_deleted.cmp(&b.lines_deleted),
        SortKey::LinesDelta => a.lines_delta().cmp(&b.lines_delta()),
        SortKey::BinaryAdded => a.binary_added.cmp(&b.binary_added),
        SortKey::BinaryDeleted => a.binary_deleted.cmp(&b.binary_deleted),
        // A PR-only contributor (no commit date) sorts after everyone with a date.
        SortKey::FirstCommit => dated(a.first_commit).cmp(&dated(b.first_commit)),
        SortKey::LastCommit => dated(a.last_commit).cmp(&dated(b.last_commit)),
    }
}

fn dated(d: &str) -> (bool, &str) {
    (d.is_empty(), d)
}

/// Contributors in display order. Ties fall back to the name (A–Z) so the order is stable.
pub fn sorted(list: &[Contributor], mode: NameMode, key: SortKey, ascending: bool) -> Vec<&Contributor> {
    let mut v: Vec<&Contributor> = list.iter().collect();
    v.sort_by(|a, b| {
        let o = compare(a, b, mode, key);
        let o = if ascending { o } else { o.reverse() };
        o.then_with(|| compare(a, b, mode, SortKey::Name)).then_with(|| a.login.cmp(b.login))
    });
    v
}

fn group(n: u64) -> String {
    let s = n.to_string();
    let mut out = String::with_capacity(s.len() + s.len() / 3);
    for (i, ch) in s.chars().enumerate() {
        if i > 0 && (s.len() - i).is_multiple_of(3) {
            out.push(',');
        }
        out.push(ch);
    }
    out
}

fn signed(n: i128) -> String {
    let g = group(u64::try_from(n.unsigned_abs()).unwrap_or(u64::MAX));
    if n < 0 { format!("−{g}") } else { format!("+{g}") }
}

fn day(iso: &str) -> &str {
    if iso.is_empty() { "—" } else { iso.get(..10).unwrap_or(iso) }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct View {
    names: NameMode,
    key: SortKey,
    ascending: bool,
    table: bool,
}

impl Default for View {
    fn default() -> Self {
        View { names: NameMode::Username, key: SortKey::FirstCommit, ascending: true, table: false }
    }
}

/// The scrolling list's height: the About dialog is a fixed-size, centred window.
const LIST_HEIGHT: f32 = 360.0;

fn profile_url(c: &Contributor) -> String {
    format!("https://github.com/{}", c.login)
}

/// A contributor's name as a link to their GitHub profile, with the whole line as its tooltip.
fn name_link(app: &mut LightcraftApp, ui: &mut egui::Ui, c: &Contributor, names: NameMode) {
    if ui.link(c.name(names)).on_hover_text(c.summary()).clicked() {
        let _ = crate::links::open(app, &profile_url(c));
    }
}

/// About ▸ Contributors: a name toggle, a sort, and the list as a grab bag or a table.
pub fn contributors_ui(app: &mut LightcraftApp, ui: &mut egui::Ui) {
    let t = Tokens::get(ui.ctx());
    let id = egui::Id::new("credits_view");
    let mut v = ui.data_mut(|d| d.get_temp::<View>(id)).unwrap_or_default();
    ui.horizontal_wrapped(|ui| {
        ui.label(crate::i18n::tr("Show"));
        for m in NameMode::ALL {
            if ui.selectable_label(v.names == m, crate::i18n::tr(m.label())).clicked() {
                v.names = m;
            }
        }
        ui.separator();
        ui.label(crate::i18n::tr("Sort"));
        egui::ComboBox::from_id_salt("credits_sort").selected_text(crate::i18n::tr(v.key.label().0)).show_ui(ui, |ui| {
            for k in SortKey::ALL {
                if ui.selectable_label(v.key == k, crate::i18n::tr(k.label().0)).clicked() {
                    v.key = k;
                    v.ascending = k.default_ascending();
                }
            }
        });
        if ui.button(if v.ascending { "▲" } else { "▼" }).on_hover_text(crate::i18n::tr("Reverse the order")).clicked() {
            v.ascending = !v.ascending;
        }
        ui.separator();
        let r = ui.selectable_label(!v.table, crate::i18n::tr("Grab bag"));
        crate::widgets::register(ui.ctx(), "button:creditsGrabBag", r.rect);
        if r.clicked() {
            v.table = false;
        }
        let r = ui.selectable_label(v.table, crate::i18n::tr("Table"));
        crate::widgets::register(ui.ctx(), "button:creditsTable", r.rect);
        if r.clicked() {
            v.table = true;
        }
    });
    let list = sorted(CONTRIBUTORS, v.names, v.key, v.ascending);
    ui.label(RichText::new(crate::i18n::tr_format!("{} contributors · {} commits", list.len(), group(TOTAL_COMMITS))).small().color(t.text_dim));
    ui.separator();
    let list_h = crate::panels::dialogs::list_height(ui, LIST_HEIGHT);
    egui::ScrollArea::both().id_salt("credits_scroll").max_height(list_h).auto_shrink([false, true]).show(ui, |ui| {
        if list.is_empty() {
            ui.label(crate::i18n::tr("No contributor data was built into this copy."));
        } else if v.table {
            table(app, ui, &list, &mut v);
        } else {
            ui.horizontal_wrapped(|ui| {
                for (i, c) in list.iter().enumerate() {
                    if i > 0 {
                        ui.label(RichText::new("·").color(t.text_dim));
                    }
                    name_link(app, ui, c, v.names);
                }
            });
        }
    });
    ui.data_mut(|d| d.insert_temp(id, v));
}

fn table(app: &mut LightcraftApp, ui: &mut egui::Ui, list: &[&Contributor], v: &mut View) {
    egui::Grid::new("credits_table").striped(true).num_columns(SortKey::ALL.len()).show(ui, |ui| {
        for k in SortKey::ALL {
            let arrow = if v.key == k { if v.ascending { " ▲" } else { " ▼" } } else { "" };
            if ui
                .button(RichText::new(format!("{}{arrow}", crate::i18n::tr(k.label().1))).strong())
                .on_hover_text(crate::i18n::tr(k.label().0))
                .clicked()
            {
                if v.key == k {
                    v.ascending = !v.ascending;
                } else {
                    v.key = k;
                    v.ascending = k.default_ascending();
                }
            }
        }
        ui.end_row();
        for c in list {
            name_link(app, ui, c, v.names);
            ui.label(group(c.prs));
            ui.label(group(c.commits));
            ui.label(group(c.lines_added));
            ui.label(group(c.lines_deleted));
            ui.label(signed(c.lines_delta()));
            ui.label(group(c.binary_added));
            ui.label(group(c.binary_deleted));
            ui.label(day(c.first_commit));
            ui.label(day(c.last_commit));
            ui.end_row();
        }
    });
}

/// About ▸ Models: AI models credited in Co-Authored-By trailers.
pub fn models_ui(ui: &mut egui::Ui) {
    if MODELS.is_empty() {
        ui.label(crate::i18n::tr("No model credits were built into this copy."));
        return;
    }
    let assisted: u64 = MODELS.iter().map(|m| m.commits).max().unwrap_or(0).max(1);
    let list_h = crate::panels::dialogs::list_height(ui, LIST_HEIGHT);
    egui::ScrollArea::both().id_salt("credits_models_scroll").max_height(list_h).auto_shrink([false, true]).show(ui, |ui| {
        egui::Grid::new("credits_models").striped(true).num_columns(6).show(ui, |ui| {
            for h in ["Company", "Model", "Version", "Commits", "% of all commits", "Lines +/−"] {
                ui.label(RichText::new(crate::i18n::tr(h)).strong());
            }
            ui.end_row();
            for m in MODELS {
                ui.label(m.company);
                ui.label(m.model);
                ui.label(m.version);
                ui.label(group(m.commits));
                ui.label(format!("{:.0}%", 100.0 * m.commits as f64 / TOTAL_COMMITS.max(assisted) as f64));
                ui.label(format!("+{} / −{}", group(m.lines_added), group(m.lines_deleted)));
                ui.end_row();
            }
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    fn c(
        login: &'static str,
        display: Option<&'static str>,
        real: Option<&'static str>,
        added: u64,
        deleted: u64,
        first: &'static str,
    ) -> Contributor {
        Contributor {
            login,
            display_name: display,
            real_name: real,
            prs: 0,
            commits: 1,
            lines_added: added,
            lines_deleted: deleted,
            binary_added: 0,
            binary_deleted: 0,
            first_commit: first,
            last_commit: first,
        }
    }

    fn people() -> [Contributor; 4] {
        [
            c("zed", None, None, 5, 50, "2026-01-02T00:00:00Z"),
            c("Bob", Some("Ann"), None, 10, 0, "2026-01-01T00:00:00Z"),
            c("alice", None, None, 7, 1, ""),
            c("carol", None, Some("Dana"), 1, 0, "2026-01-03T00:00:00Z"),
        ]
    }

    fn logins(v: &[&Contributor]) -> Vec<&'static str> {
        v.iter().map(|c| c.login).collect()
    }

    #[test]
    fn names_fall_back_to_the_username() {
        let p = c("bob", Some("Bobby"), None, 0, 0, "");
        assert_eq!(p.name(NameMode::Username), "@bob");
        assert_eq!(p.name(NameMode::DisplayName), "Bobby");
        assert_eq!(p.name(NameMode::RealName), "@bob");
    }

    #[test]
    fn alphabetical_ignores_at_and_case() {
        let all = people();
        let v = sorted(&all, NameMode::Username, SortKey::Name, true);
        assert_eq!(logins(&v), ["alice", "Bob", "carol", "zed"]);
        let v = sorted(&all, NameMode::DisplayName, SortKey::Name, true);
        assert_eq!(logins(&v), ["alice", "Bob", "carol", "zed"]); // "Ann" sorts with the @usernames
        let v = sorted(&all, NameMode::RealName, SortKey::Name, false);
        assert_eq!(logins(&v), ["zed", "carol", "Bob", "alice"]); // "Dana" between bob and zed
    }

    #[test]
    fn delta_and_dates() {
        let all = people();
        let v = sorted(&all, NameMode::Username, SortKey::LinesDelta, false);
        assert_eq!(logins(&v), ["Bob", "alice", "carol", "zed"]);
        let v = sorted(&all, NameMode::Username, SortKey::FirstCommit, true);
        assert_eq!(logins(&v), ["Bob", "zed", "carol", "alice"]); // undated last
    }

    #[test]
    fn the_committed_json_is_baked_in() {
        // contributors/contributors.json is committed, so a build always has someone to credit
        assert!(!CONTRIBUTORS.is_empty(), "build.rs produced no contributors");
        assert!(TOTAL_COMMITS > 0);
        assert!(CONTRIBUTORS.iter().all(|c| !c.login.is_empty() && !c.login.starts_with('@')));
        assert!(MODELS.iter().all(|m| !m.model.is_empty()));
    }

    #[test]
    fn formatting() {
        assert_eq!(group(1234567), "1,234,567");
        assert_eq!(group(12), "12");
        assert_eq!(signed(-1000), "−1,000");
        assert_eq!(day("2026-10-07T18:45:23Z"), "2026-10-07");
        assert_eq!(day(""), "—");
    }
}

//! Headless UI rendering: run the app's UI in an offscreen [`egui::Context`] and rasterize it on
//! the CPU ([`crate::softpaint`]) — no window, no GPU, no compositor.
//!
//! Two users:
//! - [`Headless`]: a complete windowless app session (`lightcraft-cli snapshot`, tests). It plays
//!   the role eframe plays for the desktop app: builds [`egui::RawInput`], runs `logic` + `ui`,
//!   keeps a CPU mirror of the textures, executes viewport commands (`Screenshot` is answered with
//!   a CPU-rendered frame, `InnerSize` resizes, `Close` quits). Control-protocol requests go
//!   through the very same handler as the desktop app's control server.
//! - [`HeadlessView`] inside the desktop app: `ui.screenshot {"headless": true}` (and the
//!   automatic fallback when the compositor delivers no frame, e.g. while the display sleeps)
//!   draws the app's UI into a shadow context from `logic`, which keeps ticking when the window
//!   is occluded.

use std::collections::HashMap;
use std::sync::Arc;
use std::sync::mpsc::Sender;
use std::time::{Duration, Instant};

use egui::{Color32, ColorImage, RawInput, TextureId, ViewportCommand, ViewportId};
use serde_json::{Value, json};

use crate::softpaint::{self, CpuTexture, Layered, TextureStore};
use crate::{ControlRequest, LightcraftApp};

/// Background behind the panels (eframe's default clear colour, made opaque).
const CLEAR: Color32 = Color32::from_rgb(12, 12, 12);
/// Simulated frame interval (deterministic animation time).
const FRAME_DT: f64 = 1.0 / 60.0;

/// Validate the scaled screenshot dimensions before layout or pixel allocation.
pub fn viewport_pixels(size: [f32; 2], pixels_per_point: f32) -> Result<[usize; 2], String> {
    if size.iter().any(|edge| *edge < 1.0) {
        return Err("viewport dimensions must be at least one logical point".into());
    }
    native_viewport_pixels(size, pixels_per_point)
}

fn native_viewport_pixels(size: [f32; 2], pixels_per_point: f32) -> Result<[usize; 2], String> {
    let [width, height] = size;
    if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 || !pixels_per_point.is_finite() || pixels_per_point <= 0.0 {
        return Err("viewport dimensions and scale must be finite and positive".into());
    }
    let axis = |value: f32| {
        // Match egui/scissor rounding and the existing screenshot dimension contract.
        let pixels = (value * pixels_per_point).round();
        if !(1.0..=softpaint::MAX_IMAGE_EDGE as f32).contains(&pixels) {
            return Err(format!("scaled viewport edges must be between 1 and {} pixels", softpaint::MAX_IMAGE_EDGE));
        }
        Ok(pixels as usize)
    };
    let (w, h) = (axis(width)?, axis(height)?);
    if w.checked_mul(h).is_none_or(|pixels| pixels > softpaint::MAX_IMAGE_PIXELS) {
        return Err(format!("scaled viewport exceeds {} pixels", softpaint::MAX_IMAGE_PIXELS));
    }
    Ok([w, h])
}

/// Convert an effective-point resize to the native viewport before validating pixel bounds.
/// Sub-point native edges after zooming out are valid when they round to at least one pixel.
pub fn resized_viewport(size: [f32; 2], native_pixels_per_point: f32, zoom: f32) -> Result<egui::Vec2, String> {
    if size.iter().any(|edge| !edge.is_finite() || *edge < 1.0) || !zoom.is_finite() || zoom <= 0.0 {
        return Err("resize dimensions must be at least one finite logical point with a positive zoom".into());
    }
    let native_size = egui::Vec2::from(size) * zoom;
    native_viewport_pixels([native_size.x, native_size.y], native_pixels_per_point)?;
    Ok(native_size)
}

fn bounded_viewport(size: egui::Vec2, scale: f32) -> (egui::Vec2, f32) {
    if native_viewport_pixels([size.x, size.y], scale).is_ok() { (size, scale) } else { (egui::vec2(1600.0, 1000.0), 1.0) }
}

/// An offscreen egui context with our fonts and theme, and a CPU mirror of its textures.
pub struct HeadlessView {
    pub ctx: egui::Context,
    pub textures: TextureStore,
    pub(crate) shapes: Vec<egui::epaint::ClippedShape>,
    pixels_per_point: f32,
    size: [usize; 2],
    frames: u64,
    /// The pretend host's clipboard: what the UI last copied, and what a paste request pastes.
    pub clipboard: String,
    /// Events the host owes the next frame (a paste request's paste, as a desktop host sends it).
    owed: Vec<egui::Event>,
}

impl Default for HeadlessView {
    fn default() -> Self {
        Self::new()
    }
}

impl HeadlessView {
    pub fn new() -> Self {
        let ctx = egui::Context::default();
        crate::theme::install_fonts(&ctx);
        crate::theme::apply(&ctx);
        HeadlessView {
            ctx,
            textures: TextureStore::default(),
            shapes: vec![],
            pixels_per_point: 1.0,
            size: [1600, 1000],
            frames: 0,
            clipboard: String::new(),
            owed: vec![],
        }
    }

    /// Input for one frame of a `size` (points) viewport at `pixels_per_point`.
    pub fn raw_input(size: egui::Vec2, pixels_per_point: f32, time: f64, events: Vec<egui::Event>) -> RawInput {
        let (size, pixels_per_point) = bounded_viewport(size, pixels_per_point);
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, size);
        let mut raw = RawInput {
            screen_rect: Some(rect),
            time: Some(time),
            predicted_dt: FRAME_DT as f32,
            focused: true,
            events,
            max_texture_side: Some(16384),
            ..Default::default()
        };
        let info = raw.viewports.entry(ViewportId::ROOT).or_default();
        info.native_pixels_per_point = Some(pixels_per_point);
        info.inner_rect = Some(rect);
        info.outer_rect = Some(rect);
        info.focused = Some(true);
        raw
    }

    /// Run one frame; keeps the shapes for [`Self::paint`]. Returns the root viewport's commands.
    pub fn run(&mut self, mut raw: RawInput, run_ui: impl FnMut(&mut egui::Ui)) -> Vec<ViewportCommand> {
        if let Some(rect) = raw.screen_rect {
            let native_scale = raw.viewports.get(&ViewportId::ROOT).and_then(|info| info.native_pixels_per_point).unwrap_or(1.0);
            self.size = native_viewport_pixels([rect.width(), rect.height()], native_scale).unwrap_or([0, 0]);
            // The host viewport is measured before UI zoom. Egui lays out in zoomed points;
            // retain the host's physical size while allowing text and controls to grow.
            let zoom = self.ctx.zoom_factor();
            if zoom.is_finite() && zoom > 0.0 {
                raw.screen_rect = Some(rect / zoom);
                if let Some(info) = raw.viewports.get_mut(&ViewportId::ROOT) {
                    info.inner_rect = info.inner_rect.map(|rect| rect / zoom);
                    info.outer_rect = info.outer_rect.map(|rect| rect / zoom);
                }
            }
        }
        raw.events.splice(0..0, std::mem::take(&mut self.owed));
        let mut out = self.ctx.run_ui(raw, run_ui);
        self.frames += 1;
        self.textures.apply(std::mem::take(&mut out.textures_delta));
        self.shapes = std::mem::take(&mut out.shapes);
        self.pixels_per_point = out.pixels_per_point;
        for c in &out.platform_output.commands {
            if let egui::OutputCommand::CopyText(text) = c {
                self.clipboard.clone_from(text);
            }
        }
        let commands = out.viewport_output.remove(&ViewportId::ROOT).map(|v| v.commands).unwrap_or_default();
        // what a desktop host does with a cut, copy or paste request (egui-winit): the event, next frame
        for c in &commands {
            match c {
                ViewportCommand::RequestCut => self.owed.push(egui::Event::Cut),
                ViewportCommand::RequestCopy => self.owed.push(egui::Event::Copy),
                ViewportCommand::RequestPaste if !self.clipboard.is_empty() => self.owed.push(egui::Event::Paste(self.clipboard.clone())),
                _ => {}
            }
        }
        commands
    }

    /// Frames run so far.
    pub fn frames(&self) -> u64 {
        self.frames
    }

    /// Every piece of text the last frame painted (labels, tooltips, values), in paint order.
    /// Every shape of the last frame, with `Shape::Vec` flattened.
    pub fn painted_shapes(&self) -> Vec<egui::epaint::Shape> {
        fn flat(shape: &egui::epaint::Shape, out: &mut Vec<egui::epaint::Shape>) {
            match shape {
                egui::epaint::Shape::Vec(shapes) => shapes.iter().for_each(|shape| flat(shape, out)),
                other => out.push(other.clone()),
            }
        }
        let mut out = Vec::new();
        self.shapes.iter().for_each(|s| flat(&s.shape, &mut out));
        out
    }

    pub fn painted_text(&self) -> Vec<String> {
        fn texts(shape: &egui::epaint::Shape, out: &mut Vec<String>) {
            match shape {
                egui::epaint::Shape::Text(shape) => out.push(shape.galley.job.text.clone()),
                egui::epaint::Shape::Vec(shapes) => shapes.iter().for_each(|shape| texts(shape, out)),
                _ => {}
            }
        }
        let mut out = Vec::new();
        for shape in &self.shapes {
            texts(&shape.shape, &mut out);
        }
        out
    }

    /// Size in pixels of the last frame.
    pub fn size_px(&self) -> [usize; 2] {
        self.size
    }

    /// Rasterize the last frame. `extra` textures (by id) take precedence over the context's own.
    pub fn paint(&self, extra: &HashMap<TextureId, CpuTexture>) -> ColorImage {
        if viewport_pixels([self.size[0] as f32, self.size[1] as f32], 1.0).is_err()
            || !self.pixels_per_point.is_finite()
            || self.pixels_per_point <= 0.0
        {
            return ColorImage::new([0, 0], Vec::new());
        }
        let prims = self.ctx.tessellate(self.shapes.clone(), self.pixels_per_point);
        softpaint::paint(&prims, &Layered { over: extra, base: &self.textures }, self.size_px(), self.pixels_per_point, CLEAR)
    }
}

/// A windowless app session: the app's `logic` + `ui` driven frame by frame into a
/// [`HeadlessView`], with control-protocol requests answered by the shared handler.
pub struct Headless {
    pub app: LightcraftApp,
    pub view: HeadlessView,
    /// The largest texture the pretend GPU takes (what a WebGL device may report: 2048).
    pub max_texture_side: usize,
    /// The limit egui was last told. Like a native host (egui-winit) it is reported once, not in
    /// every frame's input: code that reads the raw input sees `None` from then on (issue #652).
    reported_texture_side: Option<usize>,
    /// Logical size (points) and scale.
    pub size: egui::Vec2,
    pub pixels_per_point: f32,
    time: f64,
    frames: u64,
    pub(crate) events: Vec<egui::Event>,
    control: Sender<ControlRequest>,
    quit: bool,
    /// The simulated window is zoomed (`Maximized(true)` seen, reported back to the app like a real host).
    pub window_maximized: bool,
    /// Window-management commands the app sent (`StartDrag`, `Maximized`, …), oldest first.
    pub window_commands: Vec<ViewportCommand>,
    /// The pointer cursor the last frame asked for (what a real host would show).
    pub last_cursor: egui::CursorIcon,
}

/// A headless run (`lightcraft-cli snapshot`, tests) is a one-shot process: however it ends, it
/// first waits for an Apple Photos import its script left running (`export.addToPhotos {wait:
/// false}`), bounded, so it never abandons osascript or the import's result.
impl Drop for Headless {
    fn drop(&mut self) {
        #[cfg(not(target_arch = "wasm32"))]
        self.app.session.wait_for_photos_imports();
    }
}

impl Headless {
    /// Wrap `app` (its control channel is replaced by the driver's).
    /// Invalid dimensions fall back to 1600×1000 at scale 1; external callers can use
    /// [`viewport_pixels`] to reject them before constructing the session.
    pub fn new(app: LightcraftApp, size: [f32; 2], pixels_per_point: f32) -> Self {
        let (size, pixels_per_point) = if viewport_pixels(size, pixels_per_point).is_ok() {
            (egui::Vec2::from(size), pixels_per_point)
        } else {
            (egui::vec2(1600.0, 1000.0), 1.0)
        };
        let (tx, rx) = std::sync::mpsc::channel();
        let mut app = app.with_control(rx);
        app.headless_host = true;
        Headless {
            app,
            view: HeadlessView::new(),
            max_texture_side: 16384,
            reported_texture_side: None,
            size,
            pixels_per_point,
            time: 0.0,
            frames: 0,
            events: vec![],
            control: tx,
            quit: false,
            window_maximized: false,
            window_commands: vec![],
            last_cursor: egui::CursorIcon::Default,
        }
    }

    pub fn frames(&self) -> u64 {
        self.frames
    }

    /// Every piece of text the last frame painted ([`HeadlessView::painted_text`]).
    pub fn painted_text(&self) -> Vec<String> {
        self.view.painted_text()
    }

    /// `app.quit` was requested.
    pub fn quit_requested(&self) -> bool {
        self.quit
    }

    /// Run one frame.
    pub fn step(&mut self) {
        (self.size, self.pixels_per_point) = bounded_viewport(self.size, self.pixels_per_point);
        let mut raw = HeadlessView::raw_input(self.size, self.pixels_per_point, self.time, std::mem::take(&mut self.events));
        raw.viewports.entry(ViewportId::ROOT).or_default().maximized = Some(self.window_maximized);
        raw.max_texture_side = (self.reported_texture_side != Some(self.max_texture_side)).then_some(self.max_texture_side);
        self.reported_texture_side = Some(self.max_texture_side);
        self.app.raw_input_hook(&mut raw);
        let app = &mut self.app;
        let mut cursor = egui::CursorIcon::Default;
        let commands = self.view.run(raw, |ui| {
            app.logic(ui.ctx());
            app.ui(ui);
            cursor = ui.ctx().output(|output| output.cursor_icon);
        });
        self.last_cursor = cursor;
        self.time += FRAME_DT;
        self.frames += 1;
        for c in commands {
            match c {
                ViewportCommand::Screenshot(user_data) => {
                    let image = Arc::new(self.paint());
                    self.events.push(egui::Event::Screenshot { viewport_id: ViewportId::ROOT, user_data, image });
                }
                ViewportCommand::InnerSize(size) => {
                    // Viewport commands use current egui points, which include UI zoom.
                    if let Ok(native_size) = resized_viewport([size.x, size.y], self.pixels_per_point, self.view.ctx.zoom_factor()) {
                        self.size = native_size;
                    }
                }
                ViewportCommand::Close => self.quit = true,
                ViewportCommand::Maximized(on) => {
                    self.window_maximized = on;
                    self.window_commands.push(c);
                }
                ViewportCommand::StartDrag => self.window_commands.push(c),
                _ => {}
            }
        }
    }

    /// Is anything still in progress (renders, file-system checks the sidebar waits for, queued
    /// input)?
    pub fn busy(&self) -> bool {
        self.app.renderer.in_flight() > 0
            || crate::panels::left::fs_cached_running(&self.view.ctx) > 0
            || self.app.merge.busy()
            || self.app.scan.is_some()
            || self.app.sync.is_some()
            || self.app.sync_run.is_some()
            || self.app.import.is_some()
            || self.app.export.is_some()
            || self.app.session.denoise_busy()
            || !self.app.tasks.is_empty()
            || !self.app.synthetic.is_empty()
            || !self.events.is_empty()
    }

    /// Run frames until nothing is pending (renders finished, input consumed) for a few frames in
    /// a row, or `timeout` passes. Returns whether it settled.
    pub fn settle(&mut self, timeout: Duration) -> bool {
        let t0 = Instant::now();
        let mut quiet = 0;
        loop {
            self.step();
            if self.busy() {
                quiet = 0;
                std::thread::sleep(Duration::from_millis(1));
            } else {
                quiet += 1;
            }
            // a few quiet frames let layout and short UI animations finish
            if quiet >= 12 {
                return true;
            }
            if t0.elapsed() > timeout {
                return false;
            }
        }
    }

    /// Run frames until `done` holds or `timeout` passes (a render that finishes on a busy machine
    /// after a quiet spell, where [`Self::settle`] alone would stop too early). Returns `done`.
    pub fn step_until(&mut self, timeout: Duration, done: impl Fn(&Self) -> bool) -> bool {
        let t0 = Instant::now();
        while !done(self) {
            if t0.elapsed() > timeout {
                return false;
            }
            self.step();
            std::thread::sleep(Duration::from_millis(1));
        }
        true
    }

    /// Rasterize the last frame (with the photo textures).
    pub fn paint(&self) -> ColorImage {
        self.view.paint(&HashMap::new())
    }

    /// Settle, then render the current UI.
    pub fn snapshot(&mut self, timeout: Duration) -> ColorImage {
        self.settle(timeout);
        self.paint()
    }

    /// Tests that browse a folder in the temp directory expect it to be a Local location of its
    /// own. Where the temp directory lies inside the home folder (Windows), the sidebar lists it
    /// inside Home's tree instead, so hide Home for the test; elsewhere this does nothing.
    #[cfg(test)]
    pub(crate) fn hide_home_above(&mut self, path: &std::path::Path) {
        let home = std::env::var("HOME").or_else(|_| std::env::var("USERPROFILE")).unwrap_or_default();
        if !home.is_empty() && lightcraft_catalog::query::folder_within(&path.to_string_lossy(), &home) {
            let r = self.request("engine.execute", json!({"command": "local.hide", "params": {"path": home}}), Duration::from_secs(10));
            assert_eq!(r["ok"], true, "{r}");
        }
    }

    /// Send a control-protocol request (see [`crate::control`]) and run frames until it is
    /// answered, then until its input has been consumed. Returns `{"ok": …, "result"|"error": …}`.
    pub fn request(&mut self, method: &str, params: Value, timeout: Duration) -> Value {
        let (req, rx) = ControlRequest::new(method, params);
        if self.control.send(req).is_err() {
            return json!({"ok": false, "error": "control channel closed"});
        }
        let t0 = Instant::now();
        let reply = loop {
            self.step();
            if let Ok(v) = rx.try_recv() {
                break v;
            }
            if t0.elapsed() > timeout {
                return json!({"ok": false, "error": "timeout"});
            }
            if self.busy() {
                std::thread::sleep(Duration::from_millis(1));
            }
        };
        // let injected input (clicks, keys, drags) play out before the next request
        let t1 = Instant::now();
        while (!self.app.synthetic.is_empty() || !self.events.is_empty()) && t1.elapsed() < timeout {
            self.step();
        }
        self.step();
        reply
    }
}

/// For tests, a render offload: renders wait (stay queued) until `open` is set, then run; those
/// whose slot `fails` picks come back failed, as an undecodable raw's would. Install it with
/// `h.app.renderer.set_offload(Box::new(RenderGate::new(open.clone())))`.
#[cfg(test)]
pub(crate) struct RenderGate {
    open: std::rc::Rc<std::cell::Cell<bool>>,
    fails: fn(crate::render::Slot) -> bool,
    jobs: Vec<(crate::render::Slot, lightcraft_engine::media::RenderJob)>,
}

#[cfg(test)]
impl RenderGate {
    pub(crate) fn new(open: std::rc::Rc<std::cell::Cell<bool>>) -> Self {
        Self::failing(open, |_| false)
    }
    pub(crate) fn failing(open: std::rc::Rc<std::cell::Cell<bool>>, fails: fn(crate::render::Slot) -> bool) -> Self {
        Self { open, fails, jobs: Vec::new() }
    }
}

#[cfg(test)]
impl crate::render::RenderOffload for RenderGate {
    fn try_start(&mut self, slot: crate::render::Slot, job: lightcraft_engine::media::RenderJob) -> Option<lightcraft_engine::media::RenderJob> {
        if !self.open.get() {
            return Some(job);
        }
        self.jobs.push((slot, job));
        None
    }
    fn finished(&mut self) -> Vec<(crate::render::Slot, lightcraft_engine::media::RenderResult, f64)> {
        let fails = self.fails;
        self.jobs
            .drain(..)
            .map(|(slot, job)| {
                let mut r = job.run();
                if fails(slot) {
                    r.rendered = Err("no decoder for this raw".into());
                }
                (slot, r, 0.0)
            })
            .collect()
    }
}

