        *zone = -3.0;
    } else {
        panic!("dialog not open: {:?}", h.app.ui.dialog);
    }
    h.settle(SETTLE);
    let r = h.request("ui.dialog.confirm", json!({}), t);
    assert_eq!(r["ok"], true, "{r}");
